function fixtures() {
  const records = JSON.parse(JSON.stringify(RECORDS));
  for (const record of Object.values(records))
    for (const n of record.neighbours) n.glyphs = n.glyphs.map((i) => GLYPHS[i]);
  records.acousmatic = { ...records.acousmatic_music, requestedId: 'acousmatic' };
  return records;
}

// Runs unchanged in Chromium or a caller-supplied DOM. DOM-only evidence has no geometry claim.
async function contractSuite(mount, records, win) {
  let checks = 0;
  const check = (ok, name) => {
    if (!ok) throw Error(name);
    checks++;
  };
  const equal = (a, b, name) => check(JSON.stringify(a) === JSON.stringify(b), name);
  const freeze = (v) => {
    if (v && typeof v === 'object' && !Object.isFrozen(v)) {
      Object.values(v).forEach(freeze);
      Object.freeze(v);
    }
    return v;
  };
  freeze(records);
  const original = JSON.stringify(records);
  const doc = win.document;
  const host = doc.createElement('div');
  doc.body.append(host);
  const controller = new win.AbortController();
  const listeners = new Set();
  const pending = [];
  const calls = [];
  let selected = null;
  const ctx = Object.freeze({
    genre: Object.freeze({
      current: () => selected,
      subscribe(fn) {
        listeners.add(fn);
        return () => listeners.delete(fn);
      },
    }),
    loadGenreSimilar(id, { signal }) {
      return new Promise((resolve, reject) => pending.push({ id, signal, resolve, reject }));
    },
    openGenre: (id) => calls.push(['open', id]),
    // Deliberate honest stand-ins: no mutation or successful recipe result.
    addGenre: (id) => calls.push(['unavailable-add', id]),
    useSoundTargets: (id) => calls.push(['unavailable-targets', id]),
    announce: (text) => calls.push(['announce', text]),
    signal: controller.signal,
    storage: Object.freeze({}),
  });
  const set = (id) => {
    selected = id;
    for (const fn of listeners) fn();
  };
  const tick = () => new Promise((r) => win.setTimeout(r, 0));
  const settle = async (record, index = pending.length - 1) => {
    pending[index].resolve(record);
    await tick();
  };
  const handle = mount(host, ctx);
  check(host.textContent.includes('Choose a genre'), 'no-selection prompt');
  check(!host.textContent.includes('no sound characteristics'), 'null is not empty data');
  check(pending.length === 0, 'null selection does not load');
  check(
    host.querySelectorAll('link[rel="stylesheet"]').length === 1,
    'stylesheet loaded per mount'
  );
  check(host.querySelector('link').href.endsWith('/similar.css'), 'sibling stylesheet');
  handle.focus();
  check(doc.activeElement === host.querySelector('h2'), 'focus handle');
  for (const id of ['bluegrass', 'afrobeat', 'black_metal', 'acousmatic', 'acousmatic_music']) {
    set(id);
    check(pending.at(-1).id === id, 'requested selection forwarded');
    check(host.querySelector('[aria-busy="true"]'), 'loading state');
    await settle(records[id]);
    const rows = [...host.querySelectorAll('.genre-similar-row')];
    equal(
      rows.map((r) => r.dataset.genreId),
      records[id].neighbours.map((n) => n.id),
      id + ': full supplied order'
    );
    check(rows.length === 10, id + ': ten neighbours');
    check(!host.querySelector('[aria-busy]'), 'loading ends');
    rows.forEach((row, i) => {
      const n = records[id].neighbours[i];
      check(row.querySelector('button span').textContent === n.name, 'exact name');
      check(row.querySelector('p').textContent === n.agreements.join(' · '), 'exact agreements');
      equal(
        [...row.querySelectorAll('img')].map((g) => [g.getAttribute('src'), g.alt, g.title]),
        n.glyphs.map((g) => [g.url, '', g.label]),
        'glyph order/bytes/decorative alt'
      );
      const a = row.querySelector('a');
      check(a.getAttribute('href') === n.listenHref, 'native supplied Listen href');
      check(a.target === '_blank' && a.rel === 'noopener noreferrer', 'Listen tab semantics');
      check(
        a.getAttribute('aria-label') === `Listen to ${n.name} on YouTube`,
        'Listen accessible name'
      );
      const add = row.querySelector('button:last-child');
      check(add.textContent === 'Add', 'Add label');
      check(
        add.getAttribute('aria-label') === `Add ${n.name} to Your recipe`,
        'Add accessible name'
      );
    });
    if (id.startsWith('acousmatic')) {
      check(rows[0].dataset.genreId === 'glitch_2000s', 'canonical alias starts with glitch');
      check(
        !rows.some((r) => r.dataset.genreId === 'acousmatic_music'),
        'no canonical self neighbour'
      );
    }
    const first = rows[0];
    first.querySelector('button').click();
    equal(calls.at(-1), ['open', records[id].neighbours[0].id], 'open delegation');
    first.querySelector('button:last-child').click();
    first.querySelector('button:last-child').click();
    equal(
      calls.slice(-2),
      Array(2).fill(['unavailable-add', records[id].neighbours[0].id]),
      'repeat add delegates without fake deduplication'
    );
    [...host.querySelectorAll('button')].at(-1).click();
    equal(calls.at(-1), ['unavailable-targets', records[id].id], 'target canonical ID');
    check(!host.textContent.includes('Added'), 'no fake mutation feedback');
  }
  // Abort is advisory: deliberately resolve the old load after the new one.
  set('bluegrass');
  const old = pending.length - 1;
  set('afrobeat');
  check(pending[old].signal.aborted, 'old load aborted');
  await settle(records.afrobeat);
  await settle(records.bluegrass, old);
  check(
    host.querySelector('h2').textContent.includes(records.afrobeat.name),
    'late success ignored'
  );
  set('bluegrass');
  const failure = pending.length - 1;
  set('black_metal');
  await settle(records.black_metal);
  pending[failure].reject(Error('old failure'));
  await tick();
  check(host.querySelectorAll('.genre-similar-row').length === 10, 'late failure ignored');
  const staleButton = host.querySelector('button');
  set(null);
  const count = calls.length;
  staleButton.click();
  check(calls.length === count, 'detached stale action ignored');
  check(host.textContent.includes('Choose a genre'), 'clear selection');
  set('bluegrass');
  // Explicit empty adapter control using a real identity, NOT a catalog claim.
  await settle(freeze({ ...records.bluegrass, neighbours: [] }));
  check(
    host.textContent.includes(
      'The catalog has no sound characteristics for this genre, so it has no neighbours.'
    ),
    'exact empty message'
  );
  check(host.querySelectorAll('button,a').length === 0, 'empty has no result actions');
  set('bluegrass');
  pending.at(-1).reject(Object.assign(Error(), { code: 'LOAD_FAILED' }));
  await tick();
  check(host.textContent.includes('Check your connection'), 'load error guidance');
  const detachedRetry = host.querySelector('button');
  set('afrobeat');
  const retryRequestCount = pending.length;
  detachedRetry.click();
  check(
    pending.length === retryRequestCount,
    'stale retry cannot reload or abort current selection'
  );
  check(!pending.at(-1).signal.aborted, 'stale retry leaves new request live');
  await settle(records.afrobeat);
  set('bluegrass');
  pending.at(-1).reject(Object.assign(Error(), { code: 'LOAD_FAILED' }));
  await tick();
  const retry = host.querySelector('button');
  retry.focus();
  retry.click();
  check(doc.activeElement.textContent === 'Loading similar sounds…', 'retry loading focus');
  pending.at(-1).reject(Object.assign(Error(), { code: 'LOAD_FAILED' }));
  await tick();
  check(doc.activeElement.textContent === 'Retry', 'retry failure focus');
  host.querySelector('button').click();
  await settle(records.bluegrass);
  check(doc.activeElement === host.querySelector('h2'), 'retry success focus');
  set('bluegrass');
  pending.at(-1).reject(Object.assign(Error(), { code: 'NOT_FOUND' }));
  await tick();
  check(host.textContent.includes('Reload to see the current catalog'), 'not found guidance');
  set('bluegrass');
  const aborted = pending.at(-1);
  controller.abort();
  check(aborted.signal.aborted, 'host abort reaches loader');
  check(listeners.size === 0, 'selection unsubscribed');
  check(host.children.length === 0, 'host abort removes CSS and content');
  await settle(records.bluegrass);
  check(host.children.length === 0, 'late unmount result ignored');
  handle.unmount();
  handle.unmount();
  handle.focus();
  check(host.children.length === 0, 'idempotent cleanup');
  const dead = new win.AbortController();
  dead.abort();
  mount(host, { ...ctx, signal: dead.signal });
  check(host.children.length === 0 && listeners.size === 0, 'pre-aborted mount cleaned');
  equal(JSON.stringify(records), original, 'immutable inputs unchanged');
  host.remove();
  return checks;
}

async function browserMain() {
  const { chromium } = require('playwright');
  const modulePath = path.resolve(__dirname, '../../features/genre-similar/similar.js');
  const source = fs.readFileSync(modulePath, 'utf8');
  const css = fs.readFileSync(modulePath.replace(/\.js$/, '.css'), 'utf8');
  const browser = await chromium.launch({
    headless: true,
    chromiumSandbox: true,
    ...(process.env.CHROMIUM_PATH ? { executablePath: process.env.CHROMIUM_PATH } : {}),
  });
  try {
    for (const width of [1100, 375]) {
      const page = await browser.newPage({ viewport: { width, height: 900 } });
      await page.route('**/*', (route) => {
        const pathname = new URL(route.request().url()).pathname;
        if (pathname.endsWith('/similar.js'))
          return route.fulfill({ contentType: 'text/javascript', body: source });
        if (pathname.endsWith('/similar.css'))
          return route.fulfill({ contentType: 'text/css', body: css });
        if (pathname === '/')
          return route.fulfill({
            contentType: 'text/html',
            body: '<!doctype html><html lang="en"><title>Similar contract scenario</title><body></body></html>',
          });
        return route.abort();
      });
      await page.goto('http://similar.test/');
      const checks = await page.evaluate(
        async ({ code, records }) => {
          const { mount } = await import('/prototype/features/genre-similar/similar.js');
          const run = (0, eval)(`(${code})`);
          return run(mount, records, window);
        },
        { code: contractSuite.toString(), records: fixtures() }
      );
      console.log(`Similar standalone contract: ${checks} checks at ${width}px`);
      await page.close();
    }
  } finally {
    await browser.close();
  }
}
module.exports = { fixtures, contractSuite };
if (require.main === module)
  browserMain().catch((error) => {
    console.error(error);
    process.exitCode = 2;
  });
